document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(modal)closeModal();else if(s.panel){s.panel=false;render();$('#ai-open').focus();}else if(demo){demo=false;renderDemo();}}if(e.key==='Tab'&&modal){const focusables=$$('.modal button,.modal input,.modal textarea,.modal a,.modal select').filter(n=>!n.disabled);const first=focusables[0],last=focusables.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
